mapper.select:
SELECT project_id
FROM basic_v2_project_manage
WHERE project_start_date <= #{date}
AND (
(project_end_date IS NOT NULL AND project_end_date >= #{date})
OR project_end_date IS NULL
)
AND (
project_end_date IS NOT NULL
OR (project_scheduled_end_date IS NULL OR project_scheduled_end_date >= #{date})
)
AND
active_flg = 1;

SELECT sales_company_id
FROM basic_v2_project_manage
WHERE project_id = #{projectId}
AND
active_flg = 1;

SELECT department_id
FROM basic_v2_project_manage
WHERE project_id = #{projectId}
AND
active_flg = 1;

SELECT SUM(sales_amount)
FROM basic_v2_project_detail
WHERE project_id = #{projectId}
AND
active_flg = 1;

SELECT
sales_amount
FROM basic_v2_project_detail
WHERE
project_id = #{projectId}
AND
staff_id = #{staffId}
AND
active_flg = 1;

SELECT
amount_raised
FROM basic_v2_project_detail
WHERE
project_id = #{projectId}
AND
staff_id = #{staffId}
AND
active_flg = 1;

SELECT
sales_increment_unit_price_hour AS salesIncrementUnitPriceHour,
sales_decrement_unit_price_hour AS salesDecrementUnitPriceHour
FROM basic_v2_project_detail
WHERE
project_id = #{projectId}
AND
staff_id = #{staffId}
AND
active_flg = 1;

SELECT
upper_limit AS upperLimit,
lower_limit AS lowerLimit
FROM basic_v2_project_detail
WHERE
project_id = #{projectId}
AND
staff_id = #{staffId}
AND
active_flg = 1;

SELECT
procurement_increment_unit_price_hour AS procurementIncrementUnitPriceHour,
procurement_decrement_unit_price_hour AS procurementDecrementUnitPriceHour
FROM basic_v2_project_detail
WHERE
project_id = #{projectId}
AND
staff_id = #{staffId}
AND
active_flg = 1;
